def solution():
    # Define variables name and value
    contributions = {
        2015: 6000,
        2016: 7500,
        2017: 6000
    }
    annual_limits = {
        2015: 5500,
        2016: 5500,
        2017: 5500
    }
    monthly_penalty_rate = 0.01
    penalty_months = 12

    # Do math calculation to get the answer
    total_penalty = 0.0

    for year, contribution in contributions.items():
        over_contribution = max(0, contribution - annual_limits[year])
        total_penalty += over_contribution * monthly_penalty_rate * penalty_months

    # return answer
    return round(total_penalty, 2)
